import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const read = (relativePath) => fs.readFileSync(path.join(root, relativePath), 'utf8');
const failures = [];
const checks = [];

assert('department queue authorization is multi-role safe', fs.readFileSync('supabase/migrations/20260930012000_harden_department_queue_multirole.sql','utf8').includes('from public.user_roles ur') && fs.readFileSync('supabase/migrations/20260930012000_harden_department_queue_multirole.sql','utf8').includes('regexp_replace') && fs.readFileSync('supabase/migrations/20260930012000_harden_department_queue_multirole.sql','utf8').includes("role in ('radiologist','radiology_technician')"), 'department queues must authorize against all assigned roles and normalize department aliases');
assert('clinical transaction schema carries canonical facility attribution', ['patients','encounters','service_orders','department_queues','lab_orders','lab_results','imaging_orders','prescriptions','diagnoses'].every(name => fs.readFileSync('supabase/migrations/20260930013000_canonical_clinical_facility_attribution.sql','utf8').includes('alter table public.'+name+' add column if not exists facility_id')), 'core clinical transaction tables must carry facility attribution');
assert('clinical facility lineage is server enforced', fs.readFileSync('supabase/migrations/20260930013000_canonical_clinical_facility_attribution.sql','utf8').includes('An active facility is required for clinical transaction writes') && fs.readFileSync('supabase/migrations/20260930013000_canonical_clinical_facility_attribution.sql','utf8').includes('Facility lineage mismatch'), 'clinical writes must be bound to active/parent facility context');
assert('legacy facility attribution remains explicit', fs.readFileSync('supabase/migrations/20260930013000_canonical_clinical_facility_attribution.sql','utf8').includes('Existing rows remain nullable until explicitly reconciled'), 'legacy rows must not be silently assigned to an arbitrary facility');

function assert(name, condition, detail) {
  checks.push({ name, condition });
  if (!condition) failures.push(`${name}: ${detail}`);
}

const offline = read('src/lib/offlineSync.ts');
const workflow = read('src/lib/workflow.ts');
const serviceOrderMigration = read('supabase/migrations/20260916100000_harden_service_order_override_and_release_contract.sql');
const imagingMigration = read('supabase/migrations/20260914130000_imaging_lifecycle_server_authority.sql');
const labMigration = read('supabase/migrations/20260914111500_lab_workflow_payment_gate_reconciliation.sql');
const securityContract = read('supabase/tests/database/security_access_contract.sql');
