const reportGenerationScopeMigration = read('supabase/migrations/20260925093526_scope_report_generation_run_rbac.sql');
const encounterLifecycleMigration = read('supabase/migrations/20260925115745_encounter_lifecycle_amendments.sql');
const encounterContinuityMigration = read('supabase/migrations/20260925134409_clinical_encounter_continuity_configuration.sql');
const labResultAttentionMigration = read('supabase/migrations/20260925145941_lab_result_attention_deeplink.sql');
const clinicalOrderContinuityMigration = read('supabase/migrations/20260925141721_harden_clinical_order_linkage_and_result_notifications.sql');
const analyzeLabDocument = read('supabase/functions/analyze-lab-document/index.ts');
const anestheticAssessmentPage = read('src/pages/AnestheticAssessment.tsx');
const criticalAlertOverlay = read('src/components/CriticalAlertOverlay.tsx');
const aiClinicalHub = read('src/pages/AIClinicalHub.tsx');
const careTransitions = read('src/pages/CareTransitions.tsx');
const clinicalOperations = read('src/pages/ClinicalOperations.tsx');
