assert('report policy helpers are reconciled in migration history', reportAccessGrantMigration.includes('grant execute on function public.has_facility_access(uuid, uuid) to authenticated') && reportAccessScopeMigration.includes('revoke execute on function public.has_facility_access(uuid, uuid) from authenticated'), 'report authorization helper grants must remain reconciled to the production migration history');
assert('facility report RLS uses current-user authorization wrappers', reportAccessScopeMigration.includes('current_user_has_facility_access') && reportAccessScopeMigration.includes('current_user_has_role') && reportAccessScopeMigration.includes('create policy config_access') && reportAccessScopeMigration.includes('create policy config_admin_update'), 'facility report configuration policies must use current-user-scoped authorization wrappers');
assert('permissions RLS uses current-user role wrapper', reportAccessScopeMigration.includes('create policy permissions_authenticated_read') && reportAccessScopeMigration.includes('create policy permissions_admin_update') && reportAccessScopeMigration.includes("public.current_user_has_role('admin'::public.app_role)"), 'permissions policies must evaluate the authenticated session through the scoped role wrapper');
assert('role permissions RLS uses current-user role wrapper', reportAccessScopeMigration.includes('create policy role_permissions_read_own') && reportAccessScopeMigration.includes('create policy role_permissions_admin_update') && reportAccessScopeMigration.includes("public.current_user_has_role('admin'::public.app_role)"), 'role_permissions policies must evaluate the authenticated session through the scoped role wrapper');
assert('report generation run RLS uses current-user facility wrapper', reportGenerationScopeMigration.includes('create policy report_generation_runs_access') && reportGenerationScopeMigration.includes('public.current_user_has_facility_access(facility_id)'), 'report generation runs must use the current-user facility wrapper for authenticated reads');
assert('report generation item RLS uses current-user facility wrapper', reportGenerationScopeMigration.includes('create policy report_generation_items_access') && reportGenerationScopeMigration.includes('public.current_user_has_facility_access(r.facility_id)'), 'report generation items must use the current-user facility wrapper for authenticated reads');

assert('Clinical Operations does not expose the front-desk emergency workspace without matching protected read authorization', !clinicalOperations.includes("front_desk: ['emergency']") && !clinicalOperationsWorkspace.slice(clinicalOperationsWorkspace.indexOf("ELSIF _module='emergency'"), clinicalOperationsWorkspace.indexOf("ELSIF _module='handover'")).includes("front_desk"), 'Clinical Operations must not mount an emergency workspace that the protected read bridge does not authorize for front desk');
assert('Clinical Operations transition roles include specialist nurse parity', clinicalOperations.includes("['admin', 'practitioner', 'nurse', 'midwife', 'specialist_nurse']") && clinicalOperationsLifecycle.includes("public.has_role(uid,'specialist_nurse')"), 'specialist nurses must retain lifecycle transition parity where the server authorizes it');
assert('Clinical Operations uses server-aligned emergency lifecycle transitions', clinicalOperations.includes("if (currentStatus === 'waiting') return ['triage', 'cancelled', 'left_without_being_seen']") && clinicalOperationsLifecycle.includes("Emergency case must be triaged before treatment"), 'emergency transition controls must not advertise impossible waiting-state transitions');
assert('Clinical Operations uses server-aligned theatre lifecycle transitions', clinicalOperations.includes("requested: ['approved', 'cancelled']") && clinicalOperationsLifecycle.includes("Invalid theatre lifecycle transition"), 'theatre transition controls must follow the authoritative lifecycle');
assert('Clinical Operations uses server-aligned transfusion lifecycle transitions', clinicalOperations.includes("issued: ['running', 'cancelled']") && clinicalOperationsLifecycle.includes("Invalid transfusion lifecycle transition"), 'transfusion transition controls must follow the authoritative lifecycle');
assert('Clinical Operations avoids unsafe insurance financial transitions without adjudication inputs', clinicalOperations.includes("under_review: ['rejected', 'resubmission_required']") && insuranceLifecycle.includes('Approved amount is required') && insuranceLifecycle.includes('Paid amount is required'), 'claims queue must not advertise approval/payment transitions that require missing financial inputs');
assert('Clinical Operations supplies an emergency cancellation disposition', clinicalOperations.includes("status === 'cancelled' ? 'Cancelled in clinical operations'"), 'emergency cancellation must satisfy the server disposition requirement');

assert('admission workspace array response is handled by admission management', admissionManagement.includes('Array.isArray(workspace) ? workspace : (workspace?.admissions ?? [])'), 'admission management must tolerate the canonical array response from get_admission_workspace');
assert('admission workspace array response is handled by care transitions', careTransitions.includes('Array.isArray(a) ? a : (a?.admissions ?? [])'), 'care transitions must tolerate the canonical array response from get_admission_workspace');
assert('admission workspace array response is handled by AI nurse dashboard', aiClinicalAssist.includes('Array.isArray(admissionWorkspace) ? admissionWorkspace : (admissionWorkspace?.admissions ?? [])'), 'AI nurse dashboard must tolerate the canonical array response from get_admission_workspace');

assert('offline mutations always receive a unique idempotency key', offline.includes("const idempotencyKey = crypto.randomUUID();") && offline.includes("[IDEMPOTENCY_HEADER]: idempotencyKey"), 'queue creation must generate and persist the idempotency header');
assert('offline replay restores the persisted idempotency key', offline.includes("[IDEMPOTENCY_HEADER]: item.idempotencyKey"), 'replay must not generate a new key for an existing mutation');
assert('offline permanent failures become blocked', offline.includes("item.status = 'blocked';") && offline.includes('isPermanentFailure(response.status)'), '4xx permanent failures must remain visible for manual resolution');
assert('offline transient failures use bounded backoff', offline.includes('RETRY_BASE_DELAY_MS') && offline.includes('RETRY_MAX_DELAY_MS') && offline.includes('retryDelayMs(item.attempts)'), 'retry scheduling must remain bounded and exponential');
assert('offline queue preserves the original mutation body during replay', offline.includes('body: item.body ?? undefined'), 'replay must send the persisted payload rather than reconstructing it');

const replayStart = offline.indexOf('async function replayMutation');
const retryStart = offline.indexOf('function retryDelayMs', replayStart);
const replaySection = replayStart >= 0 && retryStart > replayStart ? offline.slice(replayStart, retryStart) : '';
const replayStripsAuthorization = /const headers = \{ \.\.\.item\.headers, \[IDEMPOTENCY_HEADER\]: item\.idempotencyKey \};\s*(?:\/\/[^\n]*\n\s*)*delete headers\.authorization;\s*(?:\/\/[^\n]*\n\s*)*if \(authHeaderProvider\)/s.test(replaySection);
assert('offline replay removes stale authorization before applying the current session', replayStripsAuthorization && replaySection.includes('if (accessToken) headers.authorization = `Bearer ${accessToken}`;'), 'replay must remove persisted Authorization unconditionally before optionally applying a fresh session token');

assert('service-order release is database-authoritative', workflow.includes("workflowRpc.rpc('release_service_order'") && serviceOrderMigration.includes('FOR UPDATE'), 'frontend release must delegate to the locked server-side lifecycle function');
assert('service-order release enforces payment before release', serviceOrderMigration.includes("Payment approval is required before release") && serviceOrderMigration.includes("v_paid < v_order.amount"), 'unpaid required service orders must not be released without an override');
assert('service-order release creates the downstream queue entry', serviceOrderMigration.includes('INSERT INTO public.department_queues') && serviceOrderMigration.includes("reason, created_by, queued_at, status") && serviceOrderMigration.includes("'queued'"), 'released work must become available to the department queue');
assert('imaging lifecycle requires server-authoritative start and completion', imagingMigration.includes('CREATE OR REPLACE FUNCTION public.start_imaging_order') && imagingMigration.includes('CREATE OR REPLACE FUNCTION public.complete_imaging_order'), 'imaging start/complete transitions must remain inside SECURITY DEFINER workflow functions');
assert('laboratory lifecycle exposes the four guarded workflow stages', ['create_lab_order_with_payment_gate', 'collect_lab_sample', 'enter_lab_result', 'approve_lab_result'].every((name) => labMigration.includes(`public.${name}`)), 'lab order, collection, result entry and approval must all remain server-authoritative');
assert('pharmacy lifecycle exposes the protected dispensing and POS workflow surface', ['find_pharmacy_alternatives', 'prepare_pharmacy_dispensing', 'confirm_pharmacy_dispense', 'create_pharmacy_pos_sale', 'confirm_pharmacy_pos_sale', 'create_pharmacy_inventory_item'].every((name) => securityContract.includes(`'${name}'`)), 'pharmacy preparation, dispensing, POS and inventory mutations must remain represented in the database security contract');
assert('insurance lifecycle exposes protected claim mutation workflow', ['create_insurance_claim_draft', 'transition_insurance_claim', 'update_insurance_claim_financials'].every((name) => securityContract.includes(`'${name}'`)), 'insurance claim creation, transition and financial mutation must remain server-authoritative');
assert('selected-invoice payment remains authenticated-only', securityContract.includes("public.pay_selected_invoice_items(uuid,uuid[],text,text)") && securityContract.includes("'selected-invoice payment collection is authenticated-only'"), 'financial payment mutation must not be exposed to anonymous clients');
assert('facility routing changes remain administrator-gated', securityContract.includes("public.set_facility_routing_mode(text)") && securityContract.includes("'facility routing mode is authenticated-only and administrator-gated'") && securityContract.includes("%has_role(auth.uid(),''admin'')%"), 'routing mode changes must remain authenticated-only and explicitly restricted to administrators');
assert('report recovery remains facility-scoped', securityContract.includes("public.recover_stale_report_run(uuid,integer)") && securityContract.includes("'report recovery is authenticated-only and facility-scoped'") && securityContract.includes('%has_facility_access(v_user,v_run.facility_id)%'), 'stale report recovery must not become a cross-facility maintenance endpoint');
assert('selected-invoice payment retains duplicate-reference idempotency', securityContract.includes("'selected-invoice payment rejects duplicate references through an idempotent replay boundary'") && securityContract.includes('%idempotent_replay%'), 'payment retries with the same reference must resolve as an idempotent replay rather than create another payment');
assert('database security contract protects lifecycle RPCs', securityContract.includes('service-order lifecycle RPCs are security-definer and authenticated-only') && securityContract.includes('laboratory workflow RPCs are security-definer and authenticated-only'), 'the database contract must continue to assert authenticated-only clinical/financial RPC execution');

assert('internal SECURITY DEFINER classification register exists', securityClassification.includes('## Explicit internal-only classifications') && securityClassification.includes('audit_patient_change()') && securityClassification.includes('notify_due_medications()') && securityClassification.includes('has_role(uuid, public.app_role)'), 'known internal trigger/scheduler/helper boundaries must remain explicitly classified');
assert('internal trigger execution boundaries are protected by the database contract', securityContract.includes('trigger-only SECURITY DEFINER helpers are outside the client execution surface') && securityContract.includes("public.audit_patient_change()") && securityContract.includes("public.validate_service_order_encounter()"), 'trigger-only SECURITY DEFINER helpers must remain inaccessible to Data API client roles');
assert('scheduler maintenance execution boundaries are protected by the database contract', securityContract.includes('scheduler-only medication maintenance helpers are outside the client execution surface') && securityContract.includes("public.notify_due_medications()") && securityContract.includes("public.lock_overdue_medication_slots()"), 'scheduler-only maintenance functions must remain inaccessible to Data API client roles');
assert('arbitrary-user authorization probes remain outside the client surface', securityContract.includes('arbitrary-user authorization helper probes are outside the client execution surface') && securityContract.includes("public.has_role(uuid,public.app_role)") && securityContract.includes("public.has_facility_access(uuid,uuid)"), 'authorization helpers that accept arbitrary user IDs must not be exposed through the Data API');

assert('protected clinical routes have a client-side role gate', roleGuard.includes('allowedRoles') && appRoutes.includes('<RoleGuard allowedRoles={nursingRoles}>') && appRoutes.includes('<RoleGuard allowedRoles={insuranceRoles}>') && appRoutes.includes('<RoleGuard allowedRoles={emergencyRoles}>') && appRoutes.includes('<RoleGuard allowedRoles={theatreRoles}>') && appRoutes.includes('<RoleGuard allowedRoles={transfusionRoles}>'), 'protected workflow pages must not issue known-forbidden Data API requests for unauthorized roles');
assert('laboratory routes match the clinical workflow role boundary', appRoutes.includes('const laboratoryWorkspaceRoles') && appRoutes.includes('<Route path="/laboratory" element={<RoleGuard allowedRoles={laboratoryWorkspaceRoles}>') && appRoutes.includes('<Route path="/results-entry" element={<RoleGuard allowedRoles={laboratoryWorkspaceRoles}>'), 'laboratory pages must not mount their protected catalogue/order reads for unauthorized roles');
assert('pharmacy routes match the pharmacy workflow role boundary', appRoutes.includes("const pharmacyRoles = ['admin', 'pharmacist']") && appRoutes.includes('<Route path="/pharmacy" element={<RoleGuard allowedRoles={pharmacyRoles}>') && appRoutes.includes('<Route path="/inventory" element={<RoleGuard allowedRoles={pharmacyRoles}>'), 'pharmacy pages must not mount inventory/POS reads for unauthorized roles');
assert('medication administration route matches the MAR RLS boundary', appRoutes.includes('<Route path="/medications" element={<RoleGuard allowedRoles={clinicalRoles}>'), 'MAR reads must not mount for roles outside the clinical medication-administration boundary');
assert('maternity route matches the maternity RLS boundary', appRoutes.includes('<Route path="/maternity" element={<RoleGuard allowedRoles={nursingRoles}>'), 'maternity reads must not mount for roles outside the maternity clinical boundary');
assert('imaging and procedure routes match their clinical RLS boundary', appRoutes.includes('const radiologyWorkspaceRoles') && appRoutes.includes('<Route path="/imaging" element={<RoleGuard allowedRoles={radiologyWorkspaceRoles}>') && appRoutes.includes('<Route path="/procedures" element={<RoleGuard allowedRoles={clinicalRoles}>') && appRoutes.includes('<Route path="/anesthesia" element={<RoleGuard allowedRoles={clinicalRoles}>'), 'protected diagnostic/procedure reads must not mount for unauthorized roles');
assert('AI clinical and administrator routes are explicitly gated', appRoutes.includes('<Route path="/ai-clinical" element={<RoleGuard allowedRoles={clinicalRoles}>') && appRoutes.includes("<Route path=\"/admin/users\" element={<RoleGuard allowedRoles={['admin','it_admin','system_superuser']}><AdminUsers />"), 'AI clinical context and role-management requests must not mount for unauthorized roles');
assert('accounts approval route is role-gated', appRoutes.includes('const accountsRoles') && appRoutes.includes('<Route path="/accounts-approvals" element={<RoleGuard allowedRoles={accountsRoles}>'), 'billing release and override actions must not be mounted for unauthorized roles');
assert('reporting routes are administrator-gated', appRoutes.includes('const reportsRoles') && appRoutes.includes('<Route path="/reports" element={<RoleGuard allowedRoles={reportsRoles}>') && appRoutes.includes('<Route path="/reports/submissions" element={<RoleGuard allowedRoles={reportsRoles}>'), 'facility/report configuration and submission pages must not issue facility reads without the administrator boundary');
assert('workflow summary avoids direct admissions reads', !workflowSummary.includes("from('admissions')"), 'dashboard navigation surfaces must not bypass the server-authorized admissions boundary');
assert('workflow summary is role-specific', workflowSummary.includes('appointmentRoles') && workflowSummary.includes('clinicalRoles') && workflowSummary.includes('canAppointments') && workflowSummary.includes("if (role === 'radiologist')") && workflowSummary.includes("if (role === 'radiology_technician')") && workflowSummary.includes("if (role === 'canteen')"), 'quick access must be explicitly scoped to operational roles rather than generic cross-department shortcuts');

assert('migration workspace exposes the required enterprise data domains', ['stg_diagnoses','service_tariffs','legacy_clinical_records'].every((name) => dataImport.includes(name)), 'data import must support Ghana STG diagnoses, services/tariffs and legacy clinical records');
assert('legacy migration is staged before native clinical promotion', dataImport.includes("stage_data_migration_rows") && migrationFoundation.includes('CREATE TABLE IF NOT EXISTS public.legacy_clinical_records') && migrationFoundation.includes("migration_status TEXT NOT NULL DEFAULT 'staged'"), 'external clinical records must preserve provenance and remain staged for reconciliation');
assert('migration foundation is administrator-controlled', migrationFoundation.includes('admins manage migration batches') && migrationFoundation.includes('admins manage migration rows') && migrationFoundation.includes("Administrator access required"), 'migration staging must remain administrator-only');
assert('STG and tariff imports use governed server-side RPCs', dataImport.includes("import_stg_diagnoses") && dataImport.includes("import_service_tariffs") && migrationRpcs.includes('REVOKE ALL ON FUNCTION public.import_stg_diagnoses') && migrationRpcs.includes('REVOKE ALL ON FUNCTION public.import_service_tariffs'), 'reference-data promotion must not depend on unrestricted direct table writes');
assert('master-data catalogue exists', migrationFoundation.includes('CREATE TABLE IF NOT EXISTS public.system_master_data') && migrationFoundation.includes("domain,code,source_system"), 'enterprise master-data metadata must have a governed catalogue');
assert('legacy reconciliation stores explicit provenance and matching evidence', migrationReconciliation.includes('match_confidence') && migrationReconciliation.includes('match_method') && migrationReconciliation.includes('reconciled_by') && migrationReconciliation.includes('reconciled_at'), 'legacy matching must preserve actor, timestamp and method/confidence evidence');
assert('legacy validation requires patient matching and chronology', migrationReconciliation.includes('Patient reconciliation is required') && migrationReconciliation.includes('occurred_at is required') && migrationReconciliation.includes('match confidence must be at least 0.85'.replace('match confidence must be','Match confidence must be')), 'legacy promotion readiness must require an identified patient and valid chronology');
assert('legacy approval and promotion are separate guarded transitions', migrationReconciliation.includes('approve_legacy_migration_batch') && migrationReconciliation.includes("status='importing'") && migrationReconciliation.includes('promote_legacy_migration_batch') && /IF\s+v_batch\.status\s*<>\s*'importing'/.test(migrationReconciliation), 'approval must precede promotion and the transitions must remain server-authoritative');
assert('legacy promotion cannot write native clinical tables', migrationReconciliationSql.includes('INSERT INTO public.legacy_clinical_records') && !migrationReconciliationSql.includes('INSERT INTO public.encounters') && !migrationReconciliationSql.includes('INSERT INTO public.prescriptions') && !migrationReconciliationSql.includes('INSERT INTO public.lab_results'), 'legacy promotion must remain isolated from native clinical mutation');
assert('legacy reconciliation UI exposes match, validate, approve and promote controls', ['get_legacy_patient_candidates','reconcile_legacy_migration_row','validate_legacy_migration_batch','approve_legacy_migration_batch','promote_legacy_migration_batch'].every((name) => dataImport.includes(name)), 'administrators must have an explicit governed reconciliation workflow rather than an implicit import side effect');
assert('triage fields start empty and use sourced reference helpers', triageForm.includes("patientId: ''") && triageForm.includes('useClinicalReferences') && triageForm.includes('aria-describedby') && !triageForm.includes('90–120 mmHg') && !triageForm.includes('95–100%'), 'vital-sign inputs must not preload example values or hardcode clinical ranges; reference guidance must come from the reference store');
assert('triage abnormal values trigger immediate clinical attention', triageForm.includes('alerts.length > 0') && triageForm.includes('normalReference(parameter)') && triageForm.includes('role="alert"'), 'values outside a configured reference range must surface an immediate alert before save');
assert('inpatient movement ledger is append-only to authenticated clients', inpatientTransferMigration.includes('CREATE TABLE IF NOT EXISTS public.inpatient_bed_movements') && inpatientTransferMigration.includes('REVOKE INSERT, UPDATE, DELETE ON public.inpatient_bed_movements FROM authenticated'), 'bed movement history must not be directly mutated by the browser');
assert('inpatient transfer is an authenticated server-authoritative workflow', inpatientTransferMigration.includes('CREATE OR REPLACE FUNCTION public.transfer_patient_ward_bed_workflow') && inpatientTransferMigration.includes('SECURITY DEFINER') && inpatientTransferMigration.includes("GRANT EXECUTE ON FUNCTION public.transfer_patient_ward_bed_workflow") && inpatientTransferMigration.includes("public.has_role(uid,'nurse')"), 'bed movement must execute through an explicit clinical workflow with server-side role validation');
assert('inpatient transfer locks the admission and destination bed', inpatientTransferMigration.includes('FOR UPDATE') && inpatientTransferMigration.includes('v_destination') && inpatientTransferMigration.includes('v_admission'), 'movement must serialize competing placement/transfer operations');
assert('inpatient transfer requires an available destination bed', inpatientTransferMigration.includes("v_destination.status <> 'available' OR v_destination.patient_id IS NOT NULL") && inpatientTransferMigration.includes("RAISE EXCEPTION 'Destination bed is not available'"), 'a transfer must never overwrite an occupied or unavailable destination');
assert('inpatient transfer releases the source before occupying the destination', inpatientTransferMigration.includes("status = 'available'") && inpatientTransferMigration.includes("status = 'occupied'") && inpatientTransferMigration.includes('source_bed_id') && inpatientTransferMigration.includes('destination_bed_id'), 'movement must atomically reconcile both canonical bed states');
assert('admission ward and bed projections stay synchronized after movement', inpatientTransferMigration.includes('UPDATE public.admissions') && inpatientTransferMigration.includes('ward =') && inpatientTransferMigration.includes('bed = v_destination.bed_number'), 'legacy admission location fields must follow the canonical ward-bed assignment');
assert('bed movement creates a completed care-transition record and audit event', inpatientTransferMigration.includes("INSERT INTO public.care_transitions") && inpatientTransferMigration.includes("'completed'") && inpatientTransferMigration.includes("record_system_audit"), 'a completed physical movement must remain visible in continuity and audit history');
assert('Care Transitions uses the canonical movement RPC for transfers', careTransitions.includes("transfer_patient_ward_bed_workflow") && careTransitions.includes("_destination_bed_id:destinationBedId") && careTransitions.includes("_admission_id:activeAdmission.id"), 'transfer UI must not create a generic transition record without changing canonical bed state');
assert('Care Transitions derives the current bed and admission from protected workspaces', careTransitions.includes("get_admission_workspace") && careTransitions.includes("get_operational_workspace") && careTransitions.includes("sourceBed") && careTransitions.includes("activeAdmission"), 'movement UI must use server-authorized admission and ward-bed context');
assert('inpatient transfer rejects hidden duplicate occupied beds', inpatientTransferMigration.includes("patient_id = _patient_id") && inpatientTransferMigration.includes("status = 'occupied'") && inpatientTransferMigration.includes("Patient has multiple occupied ward beds"), 'movement must not create a second occupied bed when another occupied bed exists for the patient');
assert('legacy ward-bed assignment delegates to the canonical movement workflow', inpatientTransferMigration.includes('CREATE OR REPLACE FUNCTION public.assign_ward_bed') && inpatientTransferMigration.includes('RETURN public.transfer_patient_ward_bed_workflow(') && inpatientTransferMigration.includes('REVOKE ALL ON FUNCTION public.assign_ward_bed'), 'legacy assignment entry points must not bypass movement history and admission synchronization');
assert('legacy bed release cannot orphan an active admission', inpatientTransferMigration.includes('CREATE OR REPLACE FUNCTION public.release_ward_bed') && inpatientTransferMigration.includes('Active admitted patients must use the inpatient movement or discharge workflow') && inpatientTransferMigration.includes('REVOKE ALL ON FUNCTION public.release_ward_bed'), 'bed release must not clear an occupied bed while leaving an active admission without a canonical location');

assert('inpatient discharge owns occupied-bed cleanup', inpatientTransferMigration.includes('CREATE OR REPLACE FUNCTION public.discharge_admission_workflow') && inpatientTransferMigration.includes("status = 'discharged'") && inpatientTransferMigration.includes("status = 'cleaning'") && inpatientTransferMigration.includes('v_bed.id'), 'discharge must atomically transition the admission and its canonical occupied bed into the cleaning state');
assert('inpatient discharge serializes against movement and rejects duplicate occupied beds', inpatientTransferMigration.includes('pg_advisory_xact_lock') && inpatientTransferMigration.includes('Patient has multiple occupied ward beds') && inpatientTransferMigration.includes('Occupied bed does not match the admission'), 'discharge must share the patient movement lock and refuse ambiguous bed ownership');
