assert('specialty and operational domains have facility attribution', specialtyFacilityMigration.includes("['emergency_cases','maternity_episodes','fertility_cycles'") && specialtyFacilityMigration.includes('enforce_extended_facility_lineage'), 'emergency, maternity, fertility, nursing, pharmacy, insurance, procedure, transfusion and AI records must have server-enforced facility attribution');
assert('specialty facility lineage cannot be cleared or crossed', specialtyFacilityMigration.includes('Facility lineage mismatch') && specialtyFacilityMigration.includes('Facility context mismatch') && specialtyFacilityMigration.includes('Facility attribution cannot be cleared'), 'extended domains must reject client-controlled facility reassignment');
assert('specialty legacy reconciliation is controlled', specialtyFacilityReconMigration.includes('list_unresolved_clinical_facility_records') && specialtyFacilityReconMigration.includes('reconcile_extended_clinical_facility_record') && specialtyFacilityReconMigration.includes('Only administrators can reconcile clinical facility attribution'), 'extended legacy records must use the admin reconciliation control plane');

const navigationSidebar = read('src/components/layout/Sidebar.tsx');
const workspaceSearch = read('src/lib/globalWorkspaceSearch.ts');
assert('Healthcare sidebar label is canonical for every role', navigationSidebar.includes("item(Stethoscope, 'Healthcare', '/clinical-operations', 'clinical_operations')") && !navigationSidebar.includes("'Clinical Operations'") && !navigationSidebar.includes('>Clinical operations<'), 'all role sidebars must display Healthcare for the clinical-operations workspace');

const remainingFacilityMigration = read('supabase/migrations/20260930017000_complete_remaining_facility_attribution.sql');
const facilityReview = read('src/pages/admin/FacilityAttributionReview.tsx');
assert('remaining facility lineage is server enforced', remainingFacilityMigration.includes('enforce_remaining_facility_lineage') && remainingFacilityMigration.includes('Facility lineage mismatch') && remainingFacilityMigration.includes('Facility attribution cannot be cleared'), 'remaining facility-linked writes must be bound to parent or active facility context');
assert('remaining facility review UI covers all domains', ['wards','beds','anesthetic_assessments','billing_overrides','dental_records','inpatient_reviews','meal_orders','meal_plans','ophthalmology_exams','outside_lab_documents','patient_account_credits','patient_visit_authorizations','video_sessions'].every(name => facilityReview.includes("'" + name + "'")), 'facility attribution review must expose remaining unresolved domains');
assert('remaining facility reconciliation is administrator-only in UI', facilityReview.includes('list_unresolved_remaining_clinical_facility_records') && facilityReview.includes('reconcile_remaining_clinical_facility_record') && facilityReview.includes("user?.role==='it_admin'"), 'remaining facility reconciliation must remain restricted to administrators and IT administrators');
const remainingFacilityReviewMigration = read('supabase/migrations/20261006153000_reconcile_remaining_facility_review_schema.sql');
assert('remaining facility review matches canonical wards schema', remainingFacilityReviewMigration.includes("w.department") && remainingFacilityReviewMigration.includes("w.active") && !remainingFacilityReviewMigration.includes('w.ward_type'), 'remaining facility review must not reference removed ward columns');
const diagnosisFacilityRepairMigration = read('supabase/migrations/20260930017100_repair_diagnosis_facility_workflow.sql');
assert('diagnosis workflow repairs legacy parent facility context', diagnosisFacilityRepairMigration.includes("tg_table_name='diagnoses'") && diagnosisFacilityRepairMigration.includes('public.current_user_facility_id()') && diagnosisFacilityRepairMigration.includes('UPDATE public.encounters SET facility_id') && diagnosisFacilityRepairMigration.includes('REVOKE EXECUTE ON FUNCTION public.sync_child_facility_from_parent() FROM PUBLIC, anon, authenticated'), 'diagnosis authoring must recover missing parent facility context only inside the authenticated workflow while keeping the trigger inaccessible as a client RPC');

if (failures.length) {
  console.error(failures.join('\n'));
  process.exitCode = 1;
} else {
  console.log('Operational contract checks passed: ' + checks.length);
}

